class Runnable:
    def __init__(self, func):
        self.func = func

    def invoke(self, input_value):
        return self.func(input_value)

    def __or__(self, other):
        return Runnable(lambda x: other.invoke(self.invoke(x)))


def parse_dm(raw):
    return raw.strip().lower()


def classify(text):
    category = "purchase_intent" if ("price" in text or "cost" in text) else "question"
    return {"category": category, "text": text}


def format_response(classified):
    return f"[{classified['category'].upper()}] {classified['text']}"


