class VectorStore:
    def __init__(self):
        self.points = []

    def add(self, id, vector, payload):
        self.points.append({"id": id, "vector": vector, "payload": payload})

    def search(self, query_vector, top_k=3, filter_fn=None):
        candidates = self.points
        if filter_fn is not None:
            candidates = [p for p in candidates if filter_fn(p["payload"])]
        scored = [
            {**p, "score": cosine_similarity(query_vector, p["vector"])}
            for p in candidates
        ]
        scored.sort(key=lambda p: p["score"], reverse=True)
        return scored[:top_k]


store = VectorStore()
store.add("dm1", [0.9, 0.1, 0.0], {"category": "purchase_intent", "text": "How much is it?"})
store.add("dm2", [0.1, 0.9, 0.0], {"category": "question", "text": "Do you ship to India?"})
